import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  Plus, 
  Edit, 
  Trash2, 
  Upload, 
  Search, 
  MapPin, 
  Phone, 
  DollarSign,
  Package,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

const SuperadminDashboard = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview');
  const [catalogs, setCatalogs] = useState([]);
  const [vendors, setVendors] = useState([]);
  const [productCodes, setProductCodes] = useState([]);
  const [showVendorModal, setShowVendorModal] = useState(false);
  const [editingVendor, setEditingVendor] = useState(null);
  const [selectedCatalog, setSelectedCatalog] = useState(null);
  const [expandedCatalog, setExpandedCatalog] = useState(null);
  const [loading, setLoading] = useState(true);

  const [vendorFormData, setVendorFormData] = useState({
    name: '',
    phone: '',
    address: '',
    location: { type: 'Point', coordinates: [0, 0] },
    city: '',
    state: '',
    pincode: '',
    catalogId: '',
    productCode: '',
    price: '',
    transportCharges: '0'
  });

  useEffect(() => {
    const token = localStorage.getItem('adminToken');
    const info = localStorage.getItem('adminInfo');
    if (!token || !info) {
      navigate('/admin/login');
      return;
    }

    try {
      const admin = JSON.parse(info);
      if (admin.role !== 'superadmin') {
        navigate('/admin/dashboard');
      }
    } catch (err) {
      navigate('/admin/login');
    }

    fetchData();
  }, [navigate]);

  const fetchData = async () => {
    try {
      const token = localStorage.getItem('adminToken');

      // Fetch catalogs
      const catalogsRes = await fetch('http://localhost:5002/api/catalog');
      const catalogsData = await catalogsRes.json();
      setCatalogs(catalogsData);

      // Fetch product codes
      const codesRes = await fetch('http://localhost:5002/api/vendor/product-codes', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (codesRes.ok) {
        const codesData = await codesRes.json();
        setProductCodes(codesData);
      }

      // Fetch all vendors
      const vendorsRes = await fetch('http://localhost:5002/api/vendor/catalog/all', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (vendorsRes.ok) {
        const vendorsData = await vendorsRes.json();
        setVendors(vendorsData);
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddVendor = (catalog) => {
    setSelectedCatalog(catalog);
    setEditingVendor(null);
    setVendorFormData({
      name: '',
      phone: '',
      address: '',
      location: { type: 'Point', coordinates: [0, 0] },
      city: '',
      state: '',
      pincode: '',
      catalogId: catalog._id,
      productCode: '',
      price: '',
      transportCharges: '0'
    });
    setShowVendorModal(true);
  };

  const handleEditVendor = (vendor) => {
    setEditingVendor(vendor);
    setVendorFormData({
      name: vendor.name,
      phone: vendor.phone,
      address: vendor.address,
      location: vendor.location,
      city: vendor.city,
      state: vendor.state,
      pincode: vendor.pincode,
      catalogId: vendor.catalogId,
      productCode: vendor.productCode,
      price: vendor.price,
      transportCharges: vendor.transportCharges
    });
    setShowVendorModal(true);
  };

  const handleDeleteVendor = async (vendorId) => {
    if (!window.confirm('Are you sure you want to delete this vendor?')) return;

    try {
      const token = localStorage.getItem('adminToken');
      const response = await fetch(`http://localhost:5002/api/vendor/${vendorId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (response.ok) {
        setVendors(vendors.filter(v => v._id !== vendorId));
      }
    } catch (error) {
      console.error('Error deleting vendor:', error);
    }
  };

  const handleVendorSubmit = async (e) => {
    e.preventDefault();

    try {
      const token = localStorage.getItem('adminToken');
      const url = editingVendor 
        ? `http://localhost:5002/api/vendor/${editingVendor._id}`
        : 'http://localhost:5002/api/vendor';

      const method = editingVendor ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(vendorFormData)
      });

      if (response.ok) {
        setShowVendorModal(false);
        fetchData();
      }
    } catch (error) {
      console.error('Error saving vendor:', error);
    }
  };

  const getVendorsForCatalog = (catalogId) => {
    return vendors.filter(v => v.catalogId === catalogId);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-brand-yellow mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Page Title */}
        <div className="mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold text-brand-dark">Super Admin Dashboard</h1>
            <p className="text-gray-600 mt-2">Manage catalogs and vendor information</p>
          </div>
          <button
            onClick={() => {
              localStorage.removeItem('adminToken');
              localStorage.removeItem('adminInfo');
              window.dispatchEvent(new Event('adminAuthChange'));
              navigate('/admin/login');
            }}
            className="px-6 py-3 bg-gray-200 text-gray-800 rounded-lg font-semibold hover:bg-gray-300 transition"
          >
            Sign Out
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="flex gap-4 mb-8">
          <button
            onClick={() => setActiveTab('overview')}
            className={`flex items-center gap-2 px-6 py-3 rounded-lg font-semibold transition-all ${
              activeTab === 'overview' ? 'bg-brand-yellow text-brand-dark' : 'bg-white text-gray-600 hover:bg-gray-200'
            }`}
          >
            <Package size={20} />
            Overview
          </button>
          <button
            onClick={() => setActiveTab('vendors')}
            className={`flex items-center gap-2 px-6 py-3 rounded-lg font-semibold transition-all ${
              activeTab === 'vendors' ? 'bg-brand-yellow text-brand-dark' : 'bg-white text-gray-600 hover:bg-gray-200'
            }`}
          >
            <MapPin size={20} />
            Vendor Management
          </button>
        </div>

        {activeTab === 'overview' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6"
          >
            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-xl p-6 shadow-lg">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-600 text-sm">Total Catalogs</p>
                    <p className="text-3xl font-bold text-brand-dark mt-2">{catalogs.length}</p>
                  </div>
                  <Package className="text-brand-yellow" size={40} />
                </div>
              </div>
              <div className="bg-white rounded-xl p-6 shadow-lg">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-600 text-sm">Total Vendors</p>
                    <p className="text-3xl font-bold text-brand-dark mt-2">{vendors.length}</p>
                  </div>
                  <MapPin className="text-brand-yellow" size={40} />
                </div>
              </div>
              <div className="bg-white rounded-xl p-6 shadow-lg">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-600 text-sm">Product Codes</p>
                    <p className="text-3xl font-bold text-brand-dark mt-2">{productCodes.length}</p>
                  </div>
                  <Search className="text-brand-yellow" size={40} />
                </div>
              </div>
            </div>

            {/* Catalogs with Vendors */}
            <div className="bg-white rounded-xl shadow-lg p-6">
              <h2 className="text-xl font-bold text-brand-dark mb-4">Catalogs & Vendors</h2>
              <div className="space-y-4">
                {catalogs.map(catalog => {
                  const catalogVendors = getVendorsForCatalog(catalog._id);
                  const isExpanded = expandedCatalog === catalog._id;

                  return (
                    <div key={catalog._id} className="border rounded-lg overflow-hidden">
                      <div 
                        className="p-4 bg-gray-50 flex justify-between items-center cursor-pointer hover:bg-gray-100"
                        onClick={() => setExpandedCatalog(isExpanded ? null : catalog._id)}
                      >
                        <div className="flex items-center gap-4">
                          {catalog.image && (
                            <img 
                              src={`http://localhost:5002/uploads/${catalog.image}`} 
                              alt={catalog.name}
                              className="w-16 h-16 object-cover rounded"
                            />
                          )}
                          <div>
                            <h3 className="font-semibold text-brand-dark">{catalog.name}</h3>
                            <p className="text-sm text-gray-600">{catalog.categoryName}</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="text-sm text-gray-600">{catalogVendors.length} vendors</span>
                          {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                        </div>
                      </div>

                      {isExpanded && (
                        <div className="p-4">
                          <div className="flex justify-between items-center mb-4">
                            <h4 className="font-semibold text-gray-700">Vendors for this catalog</h4>
                            <button
                              onClick={() => handleAddVendor(catalog)}
                              className="flex items-center gap-2 px-4 py-2 bg-brand-yellow text-brand-dark rounded-lg hover:bg-yellow-400 transition"
                            >
                              <Plus size={16} />
                              Add Vendor
                            </button>
                          </div>

                          {catalogVendors.length === 0 ? (
                            <p className="text-gray-500 text-center py-4">No vendors added yet</p>
                          ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                              {catalogVendors.map(vendor => (
                                <div key={vendor._id} className="border rounded-lg p-4 bg-gray-50">
                                  <div className="flex justify-between items-start mb-2">
                                    <h5 className="font-semibold text-brand-dark">{vendor.name}</h5>
                                    <div className="flex gap-2">
                                      <button
                                        onClick={() => handleEditVendor(vendor)}
                                        className="text-blue-600 hover:text-blue-800"
                                      >
                                        <Edit size={16} />
                                      </button>
                                      <button
                                        onClick={() => handleDeleteVendor(vendor._id)}
                                        className="text-red-600 hover:text-red-800"
                                      >
                                        <Trash2 size={16} />
                                      </button>
                                    </div>
                                  </div>
                                  <div className="space-y-1 text-sm text-gray-600">
                                    <p className="flex items-center gap-2">
                                      <Phone size={14} />
                                      {vendor.phone}
                                    </p>
                                    <p className="flex items-center gap-2">
                                      <MapPin size={14} />
                                      {vendor.city}, {vendor.state}
                                    </p>
                                    <p className="flex items-center gap-2">
                                      <Package size={14} />
                                      Code: {vendor.productCode}
                                    </p>
                                    <p className="flex items-center gap-2">
                                      <DollarSign size={14} />
                                      ₹{vendor.price} + ₹{vendor.transportCharges} transport
                                    </p>
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </motion.div>
        )}

        {activeTab === 'vendors' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white rounded-xl shadow-lg p-6"
          >
            <h2 className="text-xl font-bold text-brand-dark mb-4">All Vendors</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {vendors.map(vendor => (
                <div key={vendor._id} className="border rounded-lg p-4 bg-gray-50">
                  <div className="flex justify-between items-start mb-2">
                    <h5 className="font-semibold text-brand-dark">{vendor.name}</h5>
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleEditVendor(vendor)}
                        className="text-blue-600 hover:text-blue-800"
                      >
                        <Edit size={16} />
                      </button>
                      <button
                        onClick={() => handleDeleteVendor(vendor._id)}
                        className="text-red-600 hover:text-red-800"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                  <div className="space-y-1 text-sm text-gray-600">
                    <p className="flex items-center gap-2">
                      <Phone size={14} />
                      {vendor.phone}
                    </p>
                    <p className="flex items-center gap-2">
                      <MapPin size={14} />
                      {vendor.city}, {vendor.state}
                    </p>
                    <p className="flex items-center gap-2">
                      <Package size={14} />
                      Code: {vendor.productCode}
                    </p>
                    <p className="flex items-center gap-2">
                      <DollarSign size={14} />
                      ₹{vendor.price} + ₹{vendor.transportCharges} transport
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        )}

        {/* Vendor Modal */}
        {showVendorModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-xl p-6 max-w-2xl w-full max-h-[90vh] overflow-y-auto">
              <h2 className="text-xl font-bold text-brand-dark mb-4">
                {editingVendor ? 'Edit Vendor' : 'Add Vendor'}
              </h2>
              <form onSubmit={handleVendorSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Vendor Name</label>
                    <input
                      type="text"
                      required
                      value={vendorFormData.name}
                      onChange={(e) => setVendorFormData({...vendorFormData, name: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Phone Number</label>
                    <input
                      type="text"
                      required
                      value={vendorFormData.phone}
                      onChange={(e) => setVendorFormData({...vendorFormData, phone: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Address</label>
                  <input
                    type="text"
                    required
                    value={vendorFormData.address}
                    onChange={(e) => setVendorFormData({...vendorFormData, address: e.target.value})}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">City</label>
                    <input
                      type="text"
                      required
                      value={vendorFormData.city}
                      onChange={(e) => setVendorFormData({...vendorFormData, city: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">State</label>
                    <input
                      type="text"
                      required
                      value={vendorFormData.state}
                      onChange={(e) => setVendorFormData({...vendorFormData, state: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Pincode</label>
                    <input
                      type="text"
                      required
                      value={vendorFormData.pincode}
                      onChange={(e) => setVendorFormData({...vendorFormData, pincode: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Latitude</label>
                    <input
                      type="number"
                      step="any"
                      required
                      value={vendorFormData.location.coordinates[1]}
                      onChange={(e) => setVendorFormData({
                        ...vendorFormData, 
                        location: { 
                          type: 'Point', 
                          coordinates: [vendorFormData.location.coordinates[0], parseFloat(e.target.value)] 
                        }
                      })}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Longitude</label>
                    <input
                      type="number"
                      step="any"
                      required
                      value={vendorFormData.location.coordinates[0]}
                      onChange={(e) => setVendorFormData({
                        ...vendorFormData, 
                        location: { 
                          type: 'Point', 
                          coordinates: [parseFloat(e.target.value), vendorFormData.location.coordinates[1]] 
                        }
                      })}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Product Code</label>
                  <input
                    type="text"
                    required
                    value={vendorFormData.productCode}
                    onChange={(e) => setVendorFormData({...vendorFormData, productCode: e.target.value})}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Price (₹)</label>
                    <input
                      type="number"
                      required
                      value={vendorFormData.price}
                      onChange={(e) => setVendorFormData({...vendorFormData, price: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Transport Charges (₹)</label>
                    <input
                      type="number"
                      value={vendorFormData.transportCharges}
                      onChange={(e) => setVendorFormData({...vendorFormData, transportCharges: e.target.value})}
                      className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-yellow focus:border-transparent"
                    />
                  </div>
                </div>

                <div className="flex gap-4 justify-end pt-4">
                  <button
                    type="button"
                    onClick={() => setShowVendorModal(false)}
                    className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 transition"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-6 py-2 bg-brand-yellow text-brand-dark rounded-lg hover:bg-yellow-400 transition"
                  >
                    {editingVendor ? 'Update Vendor' : 'Add Vendor'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SuperadminDashboard;
